import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

export function createStore({ file }) {
  let books = load();

  function load() {
    try {
      if (!existsSync(file)) return [];
      const parsed = JSON.parse(readFileSync(file, 'utf8'));
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  function persist() {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, JSON.stringify(books, null, 2));
  }

  return {
    list() {
      return [...books];
    },
    listByStatus(status) {
      return books.filter((b) => b.status === status);
    },
    get(id) {
      return books.find((b) => b.id === id) ?? null;
    },
    add({ title, author, notes, status }) {
      const now = new Date().toISOString();
      const book = {
        id: randomUUID(),
        title: String(title || '').trim(),
        author: String(author || '').trim(),
        notes: String(notes || '').trim(),
        status: status === 'finished' ? 'finished' : 'reading',
        addedAt: now,
        finishedAt: status === 'finished' ? now : null,
      };
      books.push(book);
      persist();
      return book;
    },
    updateNotes(id, notes) {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.notes = String(notes ?? '').trim();
      persist();
      return book;
    },
    markFinished(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.status = 'finished';
      book.finishedAt = new Date().toISOString();
      persist();
      return book;
    },
  };
}

import express from 'express';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export function createApp({ store }) {
  const app = express();

  app.set('view engine', 'ejs');
  app.set('views', path.join(__dirname, 'views'));
  app.use(express.urlencoded({ extended: true }));
  app.use(express.static(path.join(__dirname, 'public')));

  app.get('/', (req, res) => {
    res.render('index', {
      reading: store.listByStatus('reading'),
      finished: store.listByStatus('finished'),
    });
  });

  app.get('/books/new', (req, res) => {
    res.render('new', {
      values: { title: '', author: '', notes: '', status: 'reading' },
      error: null,
    });
  });

  app.post('/books', (req, res) => {
    const { title, author, notes, status } = req.body || {};
    if (!String(title || '').trim()) {
      return res.status(400).render('new', {
        values: { title: title || '', author: author || '', notes: notes || '', status: status || 'reading' },
        error: 'Please enter a title.',
      });
    }
    const book = store.add({ title, author, notes, status });
    res.redirect(`/books/${book.id}`);
  });

  app.get('/books/:id', (req, res) => {
    const book = store.get(req.params.id);
    if (!book) return res.status(404).render('not-found', {});
    const shareUrl = `${req.protocol}://${req.get('host')}/books/${book.id}`;
    res.render('show', { book, shareUrl });
  });

  app.post('/books/:id/finish', (req, res) => {
    const book = store.markFinished(req.params.id);
    if (!book) return res.status(404).render('not-found', {});
    res.redirect(`/books/${book.id}`);
  });

  app.post('/books/:id/notes', (req, res) => {
    const book = store.updateNotes(req.params.id, req.body?.notes);
    if (!book) return res.status(404).render('not-found', {});
    res.redirect(`/books/${book.id}`);
  });

  app.use((req, res) => {
    res.status(404).render('not-found', {});
  });

  return app;
}

import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createStore } from './store.js';
import { createApp } from './app.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const dataFile = path.join(__dirname, 'data', 'books.json');

const port = process.env.PORT || 3000;
const store = createStore({ file: dataFile });
const app = createApp({ store });

app.listen(port, () => {
  console.log(`Reading tracker running at http://localhost:${port}`);
});

:root {
  --bg: #f6f5f1;
  --surface: #ffffff;
  --text: #1f2330;
  --muted: #6b7280;
  --accent: #2d6a4f;
  --accent-strong: #1b4332;
  --border: #e3e0d8;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.5;
}

.container {
  max-width: 720px;
  margin: 0 auto;
  padding: 0 20px;
}

.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 60px;
}
.brand {
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text);
  text-decoration: none;
}
.site-header nav { display: flex; gap: 16px; align-items: center; }
.site-header nav a { color: var(--text); text-decoration: none; }
.site-header nav a:hover { text-decoration: underline; }

main { padding: 28px 20px 60px; }

h1 { font-size: 1.6rem; margin: 0 0 16px; }
h2 { font-size: 1.15rem; margin: 0 0 12px; }

.shelf { margin-bottom: 36px; }

.book-list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 8px; }
.book {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 16px;
}
.book-main { display: flex; flex-wrap: wrap; gap: 8px; align-items: baseline; }
.book-title { font-weight: 600; text-decoration: none; color: var(--text); }
.book-title:hover { color: var(--accent); }
.book-author { color: var(--muted); font-size: 0.95rem; }
.muted { color: var(--muted); font-size: 0.85rem; }

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
}

.form { display: flex; flex-direction: column; gap: 16px; }
.form label, .notes label { display: flex; flex-direction: column; gap: 6px; font-weight: 600; font-size: 0.95rem; }
input[type="text"], textarea {
  font: inherit;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  width: 100%;
}
textarea { resize: vertical; }
input:focus, textarea:focus { outline: 2px solid var(--accent); outline-offset: 1px; }

.radio-group { border: 1px solid var(--border); border-radius: 8px; padding: 12px 14px; }
.radio-group legend { font-weight: 600; font-size: 0.95rem; padding: 0 4px; }
.radio { display: inline-flex; gap: 6px; align-items: center; font-weight: 400; margin-right: 16px; }

.form-actions { display: flex; gap: 12px; align-items: center; }

.btn {
  display: inline-block;
  padding: 8px 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  text-decoration: none;
  font: inherit;
  cursor: pointer;
}
.btn:hover { border-color: var(--muted); }
.btn-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-strong); border-color: var(--accent-strong); }
.btn-small { padding: 5px 10px; font-size: 0.85rem; }
.inline { margin: 0; }

.empty { color: var(--muted); }
.error { color: #b42318; background: #fef3f2; border: 1px solid #fecdca; padding: 10px 12px; border-radius: 8px; }

.book-detail .book-author { color: var(--muted); margin: 0 0 4px; }
.book-detail h1 { margin-bottom: 8px; }
.status-badge {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  margin-bottom: 20px;
}
.status-reading { background: #e7f0ff; color: #1d4ed8; }
.status-finished { background: #e7f6ec; color: var(--accent-strong); }

.notes { margin-bottom: 24px; }
.notes-body {
  white-space: pre-wrap;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 14px 16px;
  margin-bottom: 16px;
}
.notes form { display: flex; flex-direction: column; gap: 10px; }

.share {
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid var(--border);
  color: var(--muted);
  word-break: break-all;
  font-size: 0.9rem;
}
.share a { color: var(--accent); }

.site-footer { border-top: 1px solid var(--border); background: var(--surface); }
.site-footer .container { padding: 16px 20px; }
.site-footer p { margin: 0; color: var(--muted); font-size: 0.85rem; }

