import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createStore } from '../src/store.js';
import { createApp } from '../src/app.js';

let baseUrl;
let server;
const tmp = mkdtempSync(path.join(tmpdir(), 'books-app-'));
const dataFile = path.join(tmp, 'books.json');
const store = createStore({ file: dataFile });
const app = createApp({ store });

beforeAll(() => new Promise((resolve) => {
  server = app.listen(0, () => {
    baseUrl = `http://127.0.0.1:${server.address().port}`;
    resolve();
  });
}));

afterAll(() => new Promise((resolve) => {
  server.close(() => {
    rmSync(tmp, { recursive: true, force: true });
    resolve();
  });
}));

describe('store', () => {
  it('adds, gets, and lists by status', () => {
    const dir = mkdtempSync(path.join(tmpdir(), 'books-store-'));
    const s = createStore({ file: path.join(dir, 'books.json') });
    const book = s.add({ title: 'Piranesi', author: 'Susanna Clarke', notes: 'good', status: 'reading' });
    expect(book.id).toMatch(/^[0-9a-f-]{36}$/);
    expect(s.get(book.id).title).toBe('Piranesi');
    expect(s.listByStatus('reading')).toHaveLength(1);
    expect(s.listByStatus('finished')).toHaveLength(0);
    rmSync(dir, { recursive: true, force: true });
  });

  it('marks a book finished', () => {
    const dir = mkdtempSync(path.join(tmpdir(), 'books-store-'));
    const s = createStore({ file: path.join(dir, 'books.json') });
    const book = s.add({ title: 'Done Book', status: 'reading' });
    s.markFinished(book.id);
    expect(s.get(book.id).status).toBe('finished');
    expect(s.get(book.id).finishedAt).toBeTruthy();
    rmSync(dir, { recursive: true, force: true });
  });

  it('updates notes', () => {
    const dir = mkdtempSync(path.join(tmpdir(), 'books-store-'));
    const s = createStore({ file: path.join(dir, 'books.json') });
    const book = s.add({ title: 'Notes', status: 'reading' });
    s.updateNotes(book.id, 'a new thought');
    expect(s.get(book.id).notes).toBe('a new thought');
    rmSync(dir, { recursive: true, force: true });
  });

  it('persists to disk so a fresh store reloads the same books', () => {
    const dir = mkdtempSync(path.join(tmpdir(), 'books-store-'));
    const file = path.join(dir, 'books.json');
    const s1 = createStore({ file });
    s1.add({ title: 'Reloading', status: 'reading' });
    const s2 = createStore({ file });
    expect(s2.list()).toHaveLength(1);
    expect(s2.list()[0].title).toBe('Reloading');
    rmSync(dir, { recursive: true, force: true });
  });

  it('returns null for a missing id', () => {
    const dir = mkdtempSync(path.join(tmpdir(), 'books-store-'));
    const s = createStore({ file: path.join(dir, 'books.json') });
    expect(s.get('nope')).toBeNull();
    expect(s.markFinished('nope')).toBeNull();
    expect(s.updateNotes('nope', 'x')).toBeNull();
    rmSync(dir, { recursive: true, force: true });
  });
});

describe('app (http)', () => {
  it('GET / renders both shelves', async () => {
    const res = await fetch(`${baseUrl}/`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Finished');
  });

  it('GET /books/new renders the add form', async () => {
    const res = await fetch(`${baseUrl}/books/new`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Add a book');
    expect(html).toContain('name="title"');
  });

  it('POST /books with a title redirects to the new book', async () => {
    const res = await fetch(`${baseUrl}/books`, {
      method: 'POST',
      body: new URLSearchParams({ title: 'The Tidy Kitchen', author: 'Alex', notes: '', status: 'reading' }),
      redirect: 'manual',
    });
    expect(res.status).toBe(302);
    expect(res.headers.get('location')).toMatch(/^\/books\/[0-9a-f-]{36}$/);
  });

  it('POST /books without a title returns 400 with an error', async () => {
    const res = await fetch(`${baseUrl}/books`, {
      method: 'POST',
      body: new URLSearchParams({ title: '', status: 'reading' }),
      redirect: 'manual',
    });
    expect(res.status).toBe(400);
    expect((await res.text())).toContain('Please enter a title');
  });

  it('GET /books/:id shows title, author and notes', async () => {
    const book = store.add({ title: 'Detail Book', author: 'Author A', notes: 'some notes', status: 'reading' });
    const res = await fetch(`${baseUrl}/books/${book.id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('Detail Book');
    expect(html).toContain('Author A');
    expect(html).toContain('some notes');
  });

  it('GET /books/:id shows a shareable absolute link', async () => {
    const book = store.add({ title: 'Share Me', status: 'reading' });
    const res = await fetch(`${baseUrl}/books/${book.id}`);
    const html = await res.text();
    expect(html).toContain(`${baseUrl}/books/${book.id}`);
  });

  it('POST /books/:id/finish marks it finished and redirects back', async () => {
    const book = store.add({ title: 'Finish Me', status: 'reading' });
    const res = await fetch(`${baseUrl}/books/${book.id}/finish`, { method: 'POST', redirect: 'manual' });
    expect(res.status).toBe(302);
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
    expect(store.get(book.id).status).toBe('finished');
  });

  it('updates notes via POST /books/:id/notes', async () => {
    const book = store.add({ title: 'Notes Flow', status: 'reading' });
    await fetch(`${baseUrl}/books/${book.id}/notes`, {
      method: 'POST',
      body: new URLSearchParams({ notes: 'updated note text' }),
      redirect: 'manual',
    });
    expect(store.get(book.id).notes).toBe('updated note text');
  });

  it('GET unknown book returns 404', async () => {
    const res = await fetch(`${baseUrl}/books/does-not-exist`);
    expect(res.status).toBe(404);
    expect((await res.text())).toContain('not found');
  });
});

